{
  "name": "ASI Tiger多轴运动控制器",
  "name_en": "ASI Tiger Multi-Axis Motion Controller",
  "manufacturer": "Applied Scientific Instrumentation (ASI)",
  "description": "用于显微成像与自动化实验的多轴硬件控制器。它通过串口控制电动载物台/位移轴，并可协调扫描、滤光轮、二向色镜滑块、逻辑触发、波形输出以及相机、激光和远焦等时序信号。",
  "description_en": "A multi-axis hardware controller for microscopy and automated experiments. It communicates over serial to control motorized stages/axes and can coordinate scanning, filter wheels, dichroic sliders, logic triggering, waveform output, and timing signals for cameras, lasers, and remote focus devices.",
  "tag_hints": [
    "microscope motion control",
    "motorized stage",
    "serial controller",
    "filter wheel control",
    "scan sequencing",
    "TTL logic timing",
    "galvo waveform generation",
    "ASI Tiger"
  ],
  "actions": [
    {
      "action_name": "auto-connect_to_serial",
      "description": "连接到Tiger控制器串口。",
      "description_en": "Connect to the Tiger controller over serial."
    },
    {
      "action_name": "auto-set_feedback_alignment",
      "description": "设置载台反馈校准。",
      "description_en": "Set the stage feedback alignment."
    },
    {
      "action_name": "auto-set_backlash",
      "description": "设置载台回程间隙补偿。",
      "description_en": "Set the stage backlash correction."
    },
    {
      "action_name": "auto-set_finishing_accuracy",
      "description": "设置载台终点精度。",
      "description_en": "Set the stage finishing accuracy."
    },
    {
      "action_name": "auto-set_error",
      "description": "设置载台漂移误差参数。",
      "description_en": "Set the stage drift error parameter."
    },
    {
      "action_name": "auto-disconnect_from_serial",
      "description": "断开串口连接。",
      "description_en": "Disconnect from the serial port."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查串口连接是否打开。",
      "description_en": "Check whether the serial connection is open."
    },
    {
      "action_name": "auto-report_to_console",
      "description": "向控制台或输出端报告消息。",
      "description_en": "Report a message to the console or output target."
    },
    {
      "action_name": "auto-send_command",
      "description": "向控制器发送串口命令。",
      "description_en": "Send a serial command to the controller."
    },
    {
      "action_name": "auto-read_response",
      "description": "读取控制器响应。",
      "description_en": "Read a response from the controller."
    },
    {
      "action_name": "auto-moverel",
      "description": "使多个载台轴执行相对移动。",
      "description_en": "Move multiple stage axes by relative distances."
    },
    {
      "action_name": "auto-moverel_axis",
      "description": "使单个载台轴执行相对移动。",
      "description_en": "Move one stage axis by a relative distance."
    },
    {
      "action_name": "auto-move",
      "description": "使多个载台轴移动到绝对位置。",
      "description_en": "Move multiple stage axes to absolute positions."
    },
    {
      "action_name": "auto-move_axis",
      "description": "使单个载台轴移动到绝对位置。",
      "description_en": "Move one stage axis to an absolute position."
    },
    {
      "action_name": "auto-set_max_speed",
      "description": "设置指定轴的最大速度。",
      "description_en": "Set the maximum speed for a specified axis."
    },
    {
      "action_name": "auto-is_axis_busy",
      "description": "检查指定轴是否忙碌。",
      "description_en": "Check whether a specified axis is busy."
    },
    {
      "action_name": "auto-is_device_busy",
      "description": "检查控制器是否有任一轴忙碌。",
      "description_en": "Check whether any controller axis is busy."
    },
    {
      "action_name": "auto-wait_for_device",
      "description": "等待所有运动停止。",
      "description_en": "Wait for all motion to stop."
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止所有载台运动。",
      "description_en": "Stop all stage motion immediately."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置载台速度。",
      "description_en": "Set the stage speed."
    },
    {
      "action_name": "auto-set_speed_as_percent_max",
      "description": "按最大速度百分比设置载台速度。",
      "description_en": "Set the stage speed as a percentage of the maximum."
    },
    {
      "action_name": "auto-scanr",
      "description": "定义指定轴的扫描范围参数。",
      "description_en": "Define scan range parameters for a specified axis."
    },
    {
      "action_name": "auto-scanv",
      "description": "定义扫描线与扫描区参数。",
      "description_en": "Define scan line and scan area parameters."
    },
    {
      "action_name": "auto-start_scan",
      "description": "启动载台扫描。",
      "description_en": "Start stage scanning."
    },
    {
      "action_name": "auto-stop_scan",
      "description": "停止载台扫描。",
      "description_en": "Stop stage scanning."
    },
    {
      "action_name": "auto-is_moving",
      "description": "检查载台是否正在移动。",
      "description_en": "Check whether the stage is moving."
    },
    {
      "action_name": "auto-send_filter_wheel_command",
      "description": "向滤光轮发送串口命令。",
      "description_en": "Send a serial command to the filter wheel."
    },
    {
      "action_name": "auto-select_filter_wheel",
      "description": "选择当前滤光轮。",
      "description_en": "Select the active filter wheel."
    },
    {
      "action_name": "auto-move_filter_wheel",
      "description": "将滤光轮移动到指定位置。",
      "description_en": "Move the filter wheel to a specified position."
    },
    {
      "action_name": "auto-move_filter_wheel_to_home",
      "description": "将滤光轮移动到归零位。",
      "description_en": "Move the filter wheel to its home position."
    },
    {
      "action_name": "auto-change_filter_wheel_speed",
      "description": "更改滤光轮速度设置。",
      "description_en": "Change the filter wheel speed setting."
    },
    {
      "action_name": "auto-halt_filter_wheel",
      "description": "停止滤光轮运动。",
      "description_en": "Halt filter wheel motion."
    },
    {
      "action_name": "auto-move_dichroic",
      "description": "移动电动二向色镜滑块到指定位置。",
      "description_en": "Move the motorized dichroic slider to a specified position."
    },
    {
      "action_name": "auto-square_wave",
      "description": "输出方波调制信号。",
      "description_en": "Output a square-wave modulation signal."
    },
    {
      "action_name": "auto-logic_card_on",
      "description": "打开逻辑卡输出。",
      "description_en": "Turn on the logic card output."
    },
    {
      "action_name": "auto-logic_card_off",
      "description": "关闭逻辑卡输出。",
      "description_en": "Turn off the logic card output."
    },
    {
      "action_name": "auto-logic_cell_on",
      "description": "打开内部逻辑单元。",
      "description_en": "Turn on an internal logic cell."
    },
    {
      "action_name": "auto-logic_cell_off",
      "description": "关闭内部逻辑单元。",
      "description_en": "Turn off an internal logic cell."
    },
    {
      "action_name": "auto-single_axis_waveform",
      "description": "配置单轴模拟波形输出。",
      "description_en": "Configure single-axis analog waveform output."
    },
    {
      "action_name": "auto-single_axis_mode",
      "description": "设置单轴波形模式。",
      "description_en": "Set the single-axis waveform mode."
    },
    {
      "action_name": "auto-setup_control_loop",
      "description": "配置相机、激光、远焦、振镜与载台同步的控制回路。",
      "description_en": "Configure the control loop that synchronizes the camera, laser, remote focus, galvos, and stage."
    },
    {
      "action_name": "auto-setup_laser",
      "description": "配置激光触发输出。",
      "description_en": "Configure laser triggering output."
    },
    {
      "action_name": "auto-wait_for_loop",
      "description": "等待控制回路或单次Z堆栈循环完成。",
      "description_en": "Wait for the control loop or one Z-stack cycle to complete."
    },
    {
      "action_name": "auto-setup_z_stage",
      "description": "配置Z轴载台的同步触发。",
      "description_en": "Configure synchronized triggering for the Z stage."
    },
    {
      "action_name": "auto-scan_ports",
      "description": "扫描可用串口端口。",
      "description_en": "Scan available serial COM ports."
    },
    {
      "action_name": "auto-get_default_motor_axis_sequence",
      "description": "获取默认电机轴顺序。",
      "description_en": "Get the default motor axis sequence."
    },
    {
      "action_name": "auto-get_axis_position",
      "description": "获取轴位置（控制器单位）。",
      "description_en": "Get the axis position in controller units."
    },
    {
      "action_name": "auto-get_axis_position_um",
      "description": "获取轴位置（微米）。",
      "description_en": "Get the axis position in microns."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取各轴位置。",
      "description_en": "Get the stage positions."
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取轴速度。",
      "description_en": "Get the axis speed."
    },
    {
      "action_name": "auto-get_encoder_counts_per_mm",
      "description": "获取每毫米编码器计数。",
      "description_en": "Get the encoder counts per millimeter."
    },
    {
      "action_name": "auto-get_axis_addr",
      "description": "获取轴地址映射。",
      "description_en": "Get the axis address mapping."
    }
  ]
}

